// Package upgradefixtures mechanically proves gofastr's historical upgrade paths.
//
// Two checked-in fixture apps, one generated by gofastr@v0.38.0, one by
// gofastr@v0.53.0, are each pinned to their release under
// fixtures/<version>-app/ with their own go.mod (nested modules, invisible to
// the root ./... build). Each ships a frozen pre-upgrade SQLite DB (seed.db)
// holding real rows: two auth users, owner-scoped tasks, and seeded tags.
//
// For every fixture the driver:
//  1. copies it to a temp dir;
//  2. points gofastr at the CURRENT repo tree via a `replace` directive (this
//     is how an unreleased bump lands without a published tag);
//  3. applies the fixture's migration.patch, the manual Go-source edits
//     `gofastr upgrade --apply` cannot do mechanically, one hunk per
//     upgrades.yml entry;
//  4. runs go mod tidy + go build (the mechanical steps `--apply` runs);
//  5. boots the upgraded binary against a copy of seed.db;
//  6. asserts the full runtime contract over the existing data.
//
// The driver is gated behind GOFASTR_UPGRADE_FIXTURES=1: it shells out to the
// Go toolchain, fetches modules, and boots real servers, so it never runs in
// the ordinary `go test ./...` suite. The dedicated CI job sets the env var.
//
// Run locally:
//
//	GOFASTR_UPGRADE_FIXTURES=1 go test ./evals/upgrade-fixtures/ -run TestHistoricalUpgrades -count=1 -v
package upgradefixtures

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"net"
	"net/http"
	"net/http/cookiejar"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strconv"
	"strings"
	"testing"
	"time"
)

// fixturesRoot is this package's directory (evals/upgrade-fixtures/).
func fixturesRoot(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed — cannot locate test file")
	}
	return filepath.Dir(file)
}

// repoRoot walks up from the test file to the go.mod whose module path is the
// gofastr root, the tree the `replace` directive must point at.
func repoRoot(t *testing.T) string {
	t.Helper()
	dir := fixturesRoot(t)
	for {
		gomod := filepath.Join(dir, "go.mod")
		if b, err := os.ReadFile(gomod); err == nil && bytes.Contains(b, []byte("module github.com/DonaldMurillo/gofastr")) {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			t.Fatalf("could not find gofastr repo root above %s", fixturesRoot(t))
		}
		dir = parent
	}
}

type fixture struct {
	name string // "v0.38.0-app"
	from string // "v0.38.0", the release the app was generated by
}

var historicalFixtures = []fixture{
	{"v0.38.0-app", "v0.38.0"},
	{"v0.53.0-app", "v0.53.0"},
}

func TestHistoricalUpgrades(t *testing.T) {
	if os.Getenv("GOFASTR_UPGRADE_FIXTURES") != "1" {
		t.Skip("set GOFASTR_UPGRADE_FIXTURES=1 to run the historical upgrade fixtures (shells out, boots servers, needs network)")
	}
	root := repoRoot(t)
	manifest := mustLoadManifest(t)
	for _, fx := range historicalFixtures {
		fx := fx
		t.Run(fx.name, func(t *testing.T) {
			t.Parallel()
			upgradeAndAssert(t, root, fx, manifest[fx.name])
		})
	}
}

// upgradeAndAssert is the full green path: migrate, build, boot, assert.
func upgradeAndAssert(t *testing.T, root string, fx fixture, want manifestEntry) {
	t.Helper()
	work := t.TempDir()
	appDir := filepath.Join(work, "app")
	mustCopyDir(t, filepath.Join(fixturesRoot(t), "fixtures", fx.name), appDir)

	// 1. Point gofastr at the current repo tree.
	rewriteGomodReplace(t, appDir, root)

	// 1b. The shipped detector must flag the pre-upgrade source: the notes in
	// upgrades.yml carry detect regexes, and migration.patch encodes exactly
	// the edits they demand. If the detector goes quiet here, the registry
	// stopped covering this historical path.
	assertShippedUpgradeDetector(t, root, appDir, true)

	// 2. Apply the manual migration edits (one hunk per upgrades.yml entry).
	run(t, appDir, "apply migration.patch", "git", "apply", "-p1", "migration.patch")

	// 3. Mechanical steps, exactly what `gofastr upgrade --apply` runs after
	//    the source edits: resolve modules, then compile. CGO_ENABLED=0 because
	//    the migrated app uses the pure-Go sqlite driver (v0.56.0 swap).
	run(t, appDir, "go mod tidy", "go", "mod", "tidy")
	run(t, appDir, "go build", "go", "build", "-o", filepath.Join(work, "bin"), ".")

	// 3b. Post-patch the detector must still RUN cleanly (exit 0). It is NOT
	// asserted hit-free: many registry regexes intentionally match the
	// corrected usage too (they mark lines to review, NewEntitySessionStore,
	// WithReadHooks, not pre-migration-only patterns), so "no hits after
	// patching" is not a property the registry promises.
	assertShippedUpgradeDetector(t, root, appDir, false)

	// 4. Boot the upgraded app against a copy of the frozen pre-upgrade DB.
	dbPath := filepath.Join(work, "run.db")
	mustCopyFile(t, filepath.Join(appDir, "seed.db"), dbPath)
	srv := bootApp(t, filepath.Join(work, "bin"), dbPath)
	defer srv.kill()

	base := "http://" + srv.addr
	// 5. Assertions over the migrated, data-bearing app.
	assertRuntimeContract(t, fx, base, want)
}

// assertRuntimeContract checks the observable contract survives the upgrade.
func assertRuntimeContract(t *testing.T, fx fixture, base string, want manifestEntry) {
	t.Helper()

	// SSR renders (plain HTTP GET, no browser, per the fixture contract).
	assertStatusCode(t, "GET home (SSR)", base+"/", "GET", "", nil, 200)
	assertStatusCode(t, "GET /tags (SSR)", base+"/tags", "GET", "", nil, 200)

	// OpenAPI is auth-gated by default; anonymous gets 401, a session gets 200.
	assertStatusCode(t, "GET /openapi.json anonymous", base+"/openapi.json", "GET", "", nil, 401)

	// Public CRUD + row-count survival: the seeded tags made it through.
	tags := mustGetList(t, base+"/api/tags", nil)
	if len(tags) != want.Tags {
		t.Fatalf("tags row count not preserved: got %d, manifest wants %d (migrations must not drop existing rows)", len(tags), want.Tags)
	}

	// Auth: log in BOTH users that existed in seed.db. Their password hashes
	// survived the schema bump, proving the auth_users table migrated intact.
	alice := mustLogin(t, base, "alice@ex.com", "secret123")
	bob := mustLogin(t, base, "bob@ex.com", "secret123")

	// Owner isolation: each user sees ONLY their own tasks. This is the
	// per-user scoping guarantee (EntityConfig.Scope.OwnerField) crossing the
	// v0.54.0 grouped-config migration.
	aliceTasks := mustGetList(t, base+"/api/tasks", alice)
	bobTasks := mustGetList(t, base+"/api/tasks", bob)
	if len(aliceTasks) != want.AliceTasks {
		t.Fatalf("alice's tasks not preserved/isolated: got %d, manifest wants %d", len(aliceTasks), want.AliceTasks)
	}
	if len(bobTasks) != want.BobTasks {
		t.Fatalf("bob's tasks not preserved/isolated: got %d, manifest wants %d", len(bobTasks), want.BobTasks)
	}
	// Cross-owner read is impossible over the API: alice cannot enumerate a row
	// she does not own, even though it exists in the same table.
	aliceTitles := titles(aliceTasks)
	if contains(aliceTitles, "bob task 1") {
		t.Fatalf("OWNER ISOLATION BROKEN: alice can see bob's task %v", aliceTitles)
	}

	// CRUD create still stamps the owner from the session.
	mustPost(t, base+"/api/tasks", `{"title":"alice fresh"}`, alice)
	if got := len(mustGetList(t, base+"/api/tasks", alice)); got != want.AliceTasks+1 {
		t.Fatalf("create did not stamp owner / show up: alice now has %d, want %d", got, want.AliceTasks+1)
	}
	// The new row is invisible to bob.
	if got := len(mustGetList(t, base+"/api/tasks", bob)); got != want.BobTasks {
		t.Fatalf("alice's create leaked into bob's scope: bob has %d, want %d", got, want.BobTasks)
	}

	// OpenAPI reachable with a session and names every entity's CRUD surface.
	assertStatusCode(t, "GET /openapi.json authed", base+"/openapi.json", "GET", "", alice, 200)
	spec := mustOpenAPI(t, base+"/openapi.json", alice)
	for _, table := range []string{"tasks", "tags", "users"} {
		if !spec.hasPath(table) {
			t.Fatalf("OpenAPI spec missing the %q CRUD surface after upgrade", table)
		}
	}

	// Island interaction round-trip via HTTP (no browser): the entity_list sort
	// is server-side, so a ?sort= re-render changes row order, the server half
	// of the list island the v0.38.0 generator shipped.
	if !sortChangesOrder(t, base+"/tags") {
		t.Fatalf("SSR list sort round-trip failed: ?sort= did not change order")
	}
	// Row-action RPC (data-fui-rpc) round-trip: create a tag then DELETE it via
	// the same auto-CRUD endpoint the generated island targets.
	newTag := mustPost(t, base+"/api/tags", `{"name":"rpc-probe"}`, nil)
	id := jsonField(t, newTag, "id")
	if id == "" {
		t.Fatalf("island RPC create returned no row id: %s", newTag)
	}
	del := doRequest(t, "DELETE", base+"/api/tags/"+id, "", nil)
	if del != 200 && del != 204 {
		t.Fatalf("island RPC delete (data-fui-rpc target) failed: status %d", del)
	}

	t.Logf("[%s] OK: SSR, OpenAPI, public CRUD (%d tags), auth (alice+bob), owner isolation (%d/%d tasks), create-stamps-owner, sort + row-action RPC round-trips",
		fx.name, want.Tags, want.AliceTasks, want.BobTasks)
}

// TestUpgradeFailsWhenMigrationSkipped is the negative proof: deliberately do
// NOT apply migration.patch, and `go build` must fail with a message naming the
// field the v0.54.0 grouped-config move removed. A green build here would mean
// the driver could not catch a skipped upgrade step, which defeats its purpose.
func TestUpgradeFailsWhenMigrationSkipped(t *testing.T) {
	if os.Getenv("GOFASTR_UPGRADE_FIXTURES") != "1" {
		t.Skip("set GOFASTR_UPGRADE_FIXTURES=1 to run the negative upgrade-fixture proof")
	}
	root := repoRoot(t)
	fx := historicalFixtures[0] // v0.38.0, the longest migration range
	work := t.TempDir()
	appDir := filepath.Join(work, "app")
	mustCopyDir(t, filepath.Join(fixturesRoot(t), "fixtures", fx.name), appDir)
	rewriteGomodReplace(t, appDir, root)

	// NO migration.patch, simulating skipping every manual step from
	// upgrades.yml. The flat EntityConfig fields (Public/CRUD/OwnerField/MCP)
	// were removed in v0.54.0, so the build must fail naming one of them.
	cmd := exec.CommandContext(ctxWithTimeout(t, 5*time.Minute), "go", "build", "./...")
	cmd.Dir = appDir
	cmd.Env = append(os.Environ(), "CGO_ENABLED=0", "GOFLAGS=-mod=mod")
	out, err := cmd.CombinedOutput()
	if err == nil {
		t.Fatalf("go build SUCCEEDED with the migration skipped — the driver cannot detect a skipped upgrade step (expected a compile error)")
	}
	joined := string(out)
	// The error names the removed flat field, that is the "useful message".
	if !strings.Contains(joined, "unknown field") || !regexp.MustCompile(`Public|CRUD|OwnerField|MCP|Access`).MatchString(joined) {
		t.Fatalf("build failed but the error is not actionable:\n%s", joined)
	}
	t.Logf("negative proof OK — skipping migration.patch fails the build as expected:\n%s", firstLines(joined, 8))
}

// ---------------------------------------------------------------------------
// boot/probe helpers
// ---------------------------------------------------------------------------

type runningApp struct {
	addr string
	cmd  *exec.Cmd
	logf *os.File
}

func (a *runningApp) kill() {
	if a.cmd != nil && a.cmd.Process != nil {
		_ = a.cmd.Process.Signal(os.Interrupt)
		done := make(chan struct{})
		go func() { _ = a.cmd.Wait(); close(done) }()
		select {
		case <-done:
		case <-time.After(10 * time.Second):
			_ = a.cmd.Process.Kill()
		}
	}
	if a.logf != nil {
		_ = a.logf.Close()
	}
}

// bootApp starts the upgraded binary against dbPath and waits for readiness.
func bootApp(t *testing.T, bin, dbPath string) *runningApp {
	t.Helper()
	port := freePort(t)
	addr := "127.0.0.1:" + strconv.Itoa(port)
	logf, err := os.CreateTemp("", "upgrade-fixture-*.log")
	if err != nil {
		t.Fatalf("create log: %v", err)
	}
	cmd := exec.Command(bin)
	cmd.Env = append(os.Environ(),
		"PORT="+addr,
		// foreign_keys(0), deliberately, and this is the upgrade story for a
		// whole class of existing database rather than a convenience for the
		// test.
		//
		// This app declares tasks.user_id as BOTH Scope.OwnerField and a
		// relation to `users`, so pre-v0.67 AutoMigrate wrote
		// `FOREIGN KEY (user_id) REFERENCES users(id)` into the table. The
		// framework then stamps that column from the session identity, which
		// lives in auth_users, and `users` is empty by design here (see
		// fixtures/manifest.yml). The constraint was therefore one the
		// framework violated on every create, and SQLite silently tolerated it
		// because foreign keys were off.
		//
		// v0.67 stops EMITTING that constraint, but it cannot remove one
		// already baked into a table: SQLite has no DROP CONSTRAINT and
		// AutoMigrate has no table-rebuild path. An existing database in this
		// shape therefore needs the documented escape hatch until its owner
		// rebuilds the table. That is exactly what this DSN is, and this
		// fixture is where that upgrade path is proven to work rather than
		// merely described.
		"DATABASE_URL=file:"+dbPath+"?_pragma=foreign_keys(0)",
		// Stable dev secret so the app boots deterministically (dev_mode is on).
		"JWT_SECRET=upgrade-fixture-test-secret-32chars-min!!",
		"GOFASTR_DEV_MCP=0",
	)
	cmd.Stdout = logf
	cmd.Stderr = logf
	if err := cmd.Start(); err != nil {
		t.Fatalf("start upgraded app: %v", err)
	}
	ra := &runningApp{addr: addr, cmd: cmd, logf: logf}

	base := "http://" + addr
	deadline := time.Now().Add(60 * time.Second)
	for time.Now().Before(deadline) {
		resp, err := http.Get(base + "/")
		if err == nil {
			resp.Body.Close()
			if resp.StatusCode == 200 {
				return ra
			}
		}
		time.Sleep(300 * time.Millisecond)
	}
	bootLog, _ := io.ReadAll(logf)
	ra.kill()
	t.Fatalf("upgraded app did not become ready on %s within 60s. Boot log:\n%s", addr, firstLines(string(bootLog), 40))
	return nil
}

func freePort(t *testing.T) int {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("free port: %v", err)
	}
	defer ln.Close()
	return ln.Addr().(*net.TCPAddr).Port
}

func doRequest(t *testing.T, method, url, body string, client *http.Client) int {
	t.Helper()
	var r io.Reader
	if body != "" {
		r = strings.NewReader(body)
	}
	req, err := http.NewRequest(method, url, r)
	if err != nil {
		t.Fatalf("%s %s: %v", method, url, err)
	}
	if body != "" {
		req.Header.Set("content-type", "application/json")
	}
	c := client
	if c == nil {
		c = http.DefaultClient
	}
	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("%s %s: %v", method, url, err)
	}
	defer resp.Body.Close()
	io.Copy(io.Discard, resp.Body)
	return resp.StatusCode
}

func newClient(t *testing.T) *http.Client {
	t.Helper()
	jar, err := cookiejar.New(nil)
	if err != nil {
		t.Fatalf("cookiejar: %v", err)
	}
	return &http.Client{Jar: jar, Timeout: 15 * time.Second}
}

func mustLogin(t *testing.T, base, email, pw string) *http.Client {
	t.Helper()
	c := newClient(t)
	// Try login first (the user exists in seed.db); fall back to register on a
	// fresh-DB path, then login again.
	code := doRequest(t, "POST", base+"/auth/login", fmt.Sprintf(`{"email":%q,"password":%q}`, email, pw), c)
	if code != 200 {
		// User may not exist yet on a fresh DB path, register then login.
		doRequest(t, "POST", base+"/auth/register", fmt.Sprintf(`{"email":%q,"password":%q}`, email, pw), c)
		code = doRequest(t, "POST", base+"/auth/login", fmt.Sprintf(`{"email":%q,"password":%q}`, email, pw), c)
		if code != 200 {
			t.Fatalf("login %s failed: status %d", email, code)
		}
	}
	return c
}

func mustGetList(t *testing.T, url string, c *http.Client) []map[string]any {
	t.Helper()
	cl := c
	if cl == nil {
		cl = http.DefaultClient
	}
	resp, err := cl.Get(url)
	if err != nil {
		t.Fatalf("GET %s: %v", url, err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != 200 {
		t.Fatalf("GET %s: status %d, body %s", url, resp.StatusCode, string(b))
	}
	var env struct {
		Data []map[string]any `json:"data"`
	}
	if err := json.Unmarshal(b, &env); err != nil {
		t.Fatalf("GET %s: decode list envelope: %v (body %s)", url, err, string(b))
	}
	return env.Data
}

func mustPost(t *testing.T, url, body string, c *http.Client) string {
	t.Helper()
	cl := c
	if cl == nil {
		cl = http.DefaultClient
	}
	req, _ := http.NewRequest("POST", url, strings.NewReader(body))
	req.Header.Set("content-type", "application/json")
	resp, err := cl.Do(req)
	if err != nil {
		t.Fatalf("POST %s: %v", url, err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != 201 && resp.StatusCode != 200 {
		t.Fatalf("POST %s: status %d, body %s", url, resp.StatusCode, string(b))
	}
	return string(b)
}

func assertStatusCode(t *testing.T, label, url, method, body string, c *http.Client, want int) {
	t.Helper()
	got := doRequest(t, method, url, body, c)
	if got != want {
		t.Fatalf("%s: status %d, want %d", label, got, want)
	}
}

type openAPISpec struct{ paths map[string]any }

func (s openAPISpec) hasPath(table string) bool {
	for p := range s.paths {
		if strings.Contains(p, "/"+table) {
			return true
		}
	}
	return false
}

func mustOpenAPI(t *testing.T, url string, c *http.Client) openAPISpec {
	t.Helper()
	resp, err := c.Get(url)
	if err != nil {
		t.Fatalf("GET %s: %v", url, err)
	}
	defer resp.Body.Close()
	var doc struct {
		Paths map[string]any `json:"paths"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&doc); err != nil {
		t.Fatalf("decode openapi: %v", err)
	}
	return openAPISpec{paths: doc.Paths}
}

// sortChangesOrder GETs the tags list under two sort directions and reports
// whether the first cell's text differs, the server-side half of the list
// sort island.
func sortChangesOrder(t *testing.T, url string) bool {
	t.Helper()
	first := func(dir string) string {
		resp, err := http.Get(url + "?sort=name&dir=" + dir)
		if err != nil {
			t.Fatalf("GET %s?dir=%s: %v", url, dir, err)
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		m := regexp.MustCompile(`<td[^>]*role="cell"[^>]*>([^<]+)</td>`).FindSubmatch(b)
		if m == nil {
			return ""
		}
		return string(m[1])
	}
	return first("asc") != "" && first("asc") != first("desc")
}

// ---------------------------------------------------------------------------
// manifest
// ---------------------------------------------------------------------------

type manifestEntry struct {
	AuthUsers  int `yaml:"auth_users"`
	Tasks      int `yaml:"tasks"`
	Tags       int `yaml:"tags"`
	AliceTasks int `yaml:"alice_tasks"`
	BobTasks   int `yaml:"bob_tasks"`
}

// mustLoadManifest parses fixtures/manifest.yml with a tiny stdlib line parser
// (the structure is fixed; no third-party YAML dep is warranted for one file).
func mustLoadManifest(t *testing.T) map[string]manifestEntry {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(fixturesRoot(t), "fixtures", "manifest.yml"))
	if err != nil {
		t.Fatalf("read manifest.yml: %v", err)
	}
	out := map[string]manifestEntry{}
	var cur string
	// manifest.yml shape (fixed): "fixtures:" then 2-space "  <name>:" blocks
	// whose 4-space "    key: N" lines carry the expected counts.
	for _, line := range strings.Split(string(b), "\n") {
		trim := strings.TrimSpace(line)
		if trim == "" || strings.HasPrefix(trim, "#") {
			continue
		}
		switch {
		case strings.HasPrefix(line, "    "): // a count under the current fixture
			if cur == "" {
				continue
			}
			kv := strings.SplitN(trim, ":", 2)
			if len(kv) != 2 {
				continue
			}
			val, _ := strconv.Atoi(strings.TrimSpace(kv[1]))
			e := out[cur]
			switch strings.TrimSpace(kv[0]) {
			case "auth_users":
				e.AuthUsers = val
			case "tasks":
				e.Tasks = val
			case "tags":
				e.Tags = val
			case "alice_tasks":
				e.AliceTasks = val
			case "bob_tasks":
				e.BobTasks = val
			}
			out[cur] = e
		case strings.HasPrefix(line, "  "): // a fixture block header ("  v0.38.0-app:")
			cur = strings.TrimSuffix(trim, ":")
			out[cur] = manifestEntry{}
		default: // top-level key ("fixtures:"), nothing to record
		}
	}
	if len(out) == 0 {
		t.Fatal("manifest.yml parsed to zero fixtures")
	}
	return out
}

// ---------------------------------------------------------------------------
// fs / exec helpers
// ---------------------------------------------------------------------------

func mustCopyDir(t *testing.T, src, dst string) {
	t.Helper()
	err := filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, path)
		target := filepath.Join(dst, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		return os.WriteFile(target, data, 0o644)
	})
	if err != nil {
		t.Fatalf("copy %s -> %s: %v", src, dst, err)
	}
}

func mustCopyFile(t *testing.T, src, dst string) {
	t.Helper()
	data, err := os.ReadFile(src)
	if err != nil {
		t.Fatalf("read %s: %v", src, err)
	}
	if err := os.WriteFile(dst, data, 0o644); err != nil {
		t.Fatalf("write %s: %v", dst, err)
	}
}

// rewriteGomodReplace ensures the temp copy's go.mod resolves gofastr to the
// current repo tree. It removes any prior gofastr replace line first so the
// fixture stays reusable across re-runs.
//
// It also raises the fixture's `go` directive to the repo's. Go refuses to
// build a module whose directive sits below a dependency's, and the replace
// above makes THIS repo a dependency, so a fixture frozen at the toolchain of
// its era would stop building the moment the repo's floor moves. Rewriting it
// here rather than editing the committed fixtures keeps each fixture an honest
// snapshot of the app its version generated, and keeps a toolchain bump from
// touching every fixture in the tree.
func rewriteGomodReplace(t *testing.T, appDir, repoRoot string) {
	t.Helper()
	gomod := filepath.Join(appDir, "go.mod")
	b, err := os.ReadFile(gomod)
	if err != nil {
		t.Fatalf("read go.mod: %v", err)
	}
	s := string(b)
	// Drop any existing gofastr replace directive.
	s = regexp.MustCompile(`(?m)^replace\s+github\.com/DonaldMurillo/gofastr\b[^\n]*\n`).ReplaceAllString(s, "")
	s = regexp.MustCompile(`(?m)^go\s+\S+$`).ReplaceAllString(s, "go "+repoGoDirective(t, repoRoot))
	if !strings.HasSuffix(s, "\n") {
		s += "\n"
	}
	s += "replace github.com/DonaldMurillo/gofastr => " + repoRoot + "\n"
	if err := os.WriteFile(gomod, []byte(s), 0o644); err != nil {
		t.Fatalf("write go.mod: %v", err)
	}
}

// repoGoDirective reads the `go` line out of the repository's own go.mod.
func repoGoDirective(t *testing.T, repoRoot string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(repoRoot, "go.mod"))
	if err != nil {
		t.Fatalf("read repo go.mod: %v", err)
	}
	for _, line := range strings.Split(string(data), "\n") {
		if fields := strings.Fields(line); len(fields) >= 2 && fields[0] == "go" {
			return fields[1]
		}
	}
	t.Fatalf("no go directive in %s/go.mod", repoRoot)
	return ""
}

// assertShippedUpgradeDetector runs the CURRENT tree's `gofastr upgrade`
// (registry embedded in the CLI, no network: --to pinned to the registry's
// newest version) against appDir and asserts whether its detect regexes hit.
// Pre-patch they must ("found in your project:"), post-patch they must not,
// together the two directions prove the shipped detector and the fixture's
// migration.patch describe the same upgrade.
func assertShippedUpgradeDetector(t *testing.T, root, appDir string, expectHits bool) {
	t.Helper()
	cli := filepath.Join(t.TempDir(), "gofastr-cli")
	run(t, root, "build gofastr CLI", "go", "build", "-o", cli, "./cmd/gofastr")

	target := latestRegistryVersion(t, root)
	cmd := exec.CommandContext(ctxWithTimeout(t, 2*time.Minute), cli, "upgrade", appDir, "--to", target)
	cmd.Dir = root
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("gofastr upgrade %s --to %s failed: %v\n%s", appDir, target, err, firstLines(string(out), 30))
	}
	if expectHits && !strings.Contains(string(out), "found in your project:") {
		t.Fatalf("shipped upgrade detector reported NO hits on the pre-upgrade fixture (registry coverage lost?)\n%s", firstLines(string(out), 40))
	}
}

// latestRegistryVersion parses the newest `- version: vX.Y.Z` entry from the
// CLI's embedded registry source so the detector run needs no network.
func latestRegistryVersion(t *testing.T, root string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(root, "cmd", "gofastr", "upgrades.yml"))
	if err != nil {
		t.Fatalf("read upgrades.yml: %v", err)
	}
	last := ""
	for _, line := range strings.Split(string(raw), "\n") {
		trimmed := strings.TrimSpace(line)
		if v, ok := strings.CutPrefix(trimmed, "- version: "); ok {
			last = strings.TrimSpace(v)
		}
	}
	if last == "" {
		t.Fatal("no `- version:` entries found in upgrades.yml")
	}
	return last
}

func run(t *testing.T, dir, label string, name string, args ...string) {
	t.Helper()
	cmd := exec.CommandContext(ctxWithTimeout(t, 5*time.Minute), name, args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "CGO_ENABLED=0", "GOFLAGS=-mod=mod")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("%s (%s) failed: %v\n%s", label, strings.Join(append([]string{name}, args...), " "), err, firstLines(string(out), 30))
	}
	t.Logf("%s: ok (%s)", label, firstLines(strings.TrimSpace(string(out)), 3))
}

func ctxWithTimeout(t *testing.T, d time.Duration) context.Context {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), d)
	// Register cleanup so a panicking subtest can't leak the timeout.
	t.Cleanup(cancel)
	return ctx
}

// --- small utils ---

func titles(rows []map[string]any) []string {
	out := make([]string, 0, len(rows))
	for _, r := range rows {
		if v, ok := r["title"].(string); ok {
			out = append(out, v)
		}
	}
	return out
}

func contains(s []string, v string) bool {
	for _, x := range s {
		if x == v {
			return true
		}
	}
	return false
}

func jsonField(t *testing.T, body, field string) string {
	t.Helper()
	var m map[string]any
	if err := json.Unmarshal([]byte(body), &m); err != nil {
		t.Fatalf("jsonField %q: decode: %v (body %s)", field, err, body)
	}
	// Single-record CRUD responses wrap the row under {"data":{...}}; descend.
	if inner, ok := m["data"].(map[string]any); ok {
		m = inner
	}
	if v, ok := m[field].(string); ok {
		return v
	}
	return ""
}

func firstLines(s string, n int) string {
	lines := strings.SplitN(s, "\n", n+1)
	if len(lines) > n {
		lines = append(lines[:n], "…")
	}
	return strings.Join(lines, "\n")
}
